/**
 * note のエディタは、貼り付けた markdown を変換しない。## や ** はそのまま
 * 記号として published される。だから貼る直前に落とす。
 * 見出しは note 側のボタンで、太字は選択して Ctrl+B で付ける。
 */
export function toNotePlain(s: string): string {
    return s
        .replace(/^#{1,6}\s+/gm, '')      // 見出し記号
        .replace(/\*\*(.+?)\*\*/g, '$1')  // 太字
        .replace(/^>\s+/gm, '')           // 引用記号(noteの引用ボタンで付ける)
        .replace(/^-\s+/gm, '・')          // 箇条書き
        .replace(/\n{3,}/g, '\n\n')
        .trim();
}

export interface NotePasteBlock {
    /** 画面に出す見出し。「タイトル欄に入れる」「本文 1」… */
    label: string;
    /** note に貼るテキスト(記号は落としてある) */
    text: string;
    /** このブロックを貼った直後に差し込むPNG。無ければ画像なし */
    imageAfter: string | null;
    /** note のタイトル欄に入れるブロックかどうか */
    isTitle: boolean;
}

/**
 * 本文を「貼る単位」に割る。
 *
 * 一括コピーだと、貼ったあとに画像を8箇所へ差し込むために本文を目で探すことになる。
 * 画像の位置で切っておけば、貼る→画像を入れる→次を貼る、で迷子にならない。
 */
export function toNotePasteBlocks(fullText: string, hashtags?: string[]): NotePasteBlock[] {
    const lines = fullText.split('\n');
    const blocks: NotePasteBlock[] = [];
    let buf: string[] = [];

    // 1行目はタイトル(noteのタイトル欄は本文と別)
    const title = (lines.shift() ?? '').trim();
    if (title) blocks.push({ label: 'タイトル欄に入れる', text: toNotePlain(title), imageAfter: null, isTitle: true });

    const flush = (imageAfter: string | null) => {
        const text = toNotePlain(buf.join('\n'));
        buf = [];
        if (text) blocks.push({ label: '', text, imageAfter, isTitle: false });
        else if (imageAfter && blocks.length) blocks[blocks.length - 1].imageAfter = imageAfter;
    };

    for (const line of lines) {
        const m = line.match(/^<!--\s*ここに画像:\s*(.+?)\s*-->$/);
        if (m) flush(m[1]);
        else buf.push(line);
    }
    flush(null);

    if (hashtags?.length) {
        blocks.push({ label: 'タグ(最後に貼る)', text: hashtags.map((h) => `#${h}`).join(' '), imageAfter: null, isTitle: false });
    }

    // 本文ブロックに通し番号を振る(タイトルとタグは自分のラベルを持っている)
    let n = 0;
    return blocks.map((b) => (b.label ? b : { ...b, label: `本文 ${++n}` }));
}

/** 手書き本文があればそれを返す。無い夜は null(呼び側で自動生成にフォールバック) */
export function getTonightNoteBody(night: number): TonightNoteBody | null {
    return TONIGHT_NOTE_BODIES.find((b) => b.night === night) ?? null;
}

/** note にそのまま貼れる1本のテキスト(タイトル + 本文 + タグ) */
export function getTonightNoteText(night: number): string | null {
    const b = getTonightNoteBody(night);
    if (!b) return null;
    return [b.title, '', b.body, '', b.hashtags.map((h) => `#${h}`).join(' ')].join('\n');
}
